import{_ as t,o as e,c as n,ae as a}from"./chunks/framework.Dzr56EFm.js";const c=JSON.parse('{"title":"设计趋势 - 2026-07-07","description":"","frontmatter":{"date":"2026-07-07T00:00:00.000Z","category":"UX Trend"},"headers":[],"relativePath":"daily/2026-07-07-uxtrend.md","filePath":"daily/2026-07-07-uxtrend.md"}'),o={name:"daily/2026-07-07-uxtrend.md"};function s(i,r,g,p,h,l){return e(),n("div",null,[...r[0]||(r[0]=[a('<h1 id="设计趋势-2026-07-07" tabindex="-1">设计趋势 - 2026-07-07 <a class="header-anchor" href="#设计趋势-2026-07-07" aria-label="Permalink to &quot;设计趋势 - 2026-07-07&quot;">​</a></h1><blockquote><p>AI交互方式、Prompt UX、Agent UX、Workflow</p></blockquote><h2 id="今日概览" tabindex="-1">今日概览 <a class="header-anchor" href="#今日概览" aria-label="Permalink to &quot;今日概览&quot;">​</a></h2><p>今日设计趋势资讯汇总：微软发布面向代理的UX设计原则与指南，Cursor通过AI实现直观交流，AI正改变设计工作流程，提升效率和协作。值得关注：微软的代理UX设计原则与AI代理工作流设计模式的探讨。</p><hr><h3 id="_1-面向代理的ux设计-微软的原则与指南" tabindex="-1">1. 面向代理的UX设计：微软的原则与指南 <a class="header-anchor" href="#_1-面向代理的ux设计-微软的原则与指南" aria-label="Permalink to &quot;1. 面向代理的UX设计：微软的原则与指南&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/microsoft-design/ux-design-for-agents-11336728b445" target="_blank" rel="noreferrer">UX design for agents. Microsoft principles and guidelines for…</a></p><p><strong>一句话摘要</strong>: 微软提出了一套针对代理UX设计的原则与指南。</p><p><strong>能解决什么问题</strong>: 解决数字设备中新型用户体验的设计问题。</p><p><strong>产品应用</strong>: 适用于设计代理系统，强调以人为本的原则。</p><p><strong>示例场景</strong>: 设计一个融入日常生活的AI助手。</p><hr><h3 id="_2-光标、氛围编码和手稿-ai所需的用户体验革命" tabindex="-1">2. 光标、氛围编码和手稿：AI所需的用户体验革命 <a class="header-anchor" href="#_2-光标、氛围编码和手稿-ai所需的用户体验革命" aria-label="Permalink to &quot;2. 光标、氛围编码和手稿：AI所需的用户体验革命&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://uxdesign.cc/cursor-vibe-coding-and-manus-the-ux-revolution-that-ai-needs-3d3a0f8ccdfa" target="_blank" rel="noreferrer">Cursor, “vibe coding,” and Manus: the UX revolution that AI needs | by Amy Chivavibul | UX Collective</a></p><p><strong>一句话摘要</strong>: Cursor通过将AI直接嵌入工作流程，实现与机器的直接、直观交流。</p><p><strong>能解决什么问题</strong>: 解决传统编程工具与AI助手交互不便的问题。</p><p><strong>产品应用</strong>: 可应用于开发环境，提高代码编写、测试和修复的效率。</p><p><strong>示例场景</strong>: 开发者通过Cursor直接让AI优化代码或解释函数。</p><hr><h3 id="_3-ai如何改变我的设计工作流程" tabindex="-1">3. AI如何改变我的设计工作流程 <a class="header-anchor" href="#_3-ai如何改变我的设计工作流程" aria-label="Permalink to &quot;3. AI如何改变我的设计工作流程&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/@kazdenc/how-my-design-workflow-is-changing-with-ai-bc80e7fa3323" target="_blank" rel="noreferrer">How my design workflow is changing with AI</a></p><p><strong>一句话摘要</strong>: AI使设计流程更快速、协作、减少猜测。</p><p><strong>能解决什么问题</strong>: 提高设计效率，减少从想法到原型的时间。</p><p><strong>产品应用</strong>: 适用于产品设计，通过快速原型迭代优化用户体验。</p><p><strong>示例场景</strong>: 使用Figma和Cursor快速迭代设计原型。</p><hr><h3 id="_4-ai代理工作流设计模式概览" tabindex="-1">4. AI代理工作流设计模式概览 <a class="header-anchor" href="#_4-ai代理工作流设计模式概览" aria-label="Permalink to &quot;4. AI代理工作流设计模式概览&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/binome/ai-agent-workflow-design-patterns-an-overview-cf9e1f609696" target="_blank" rel="noreferrer">AI Agent Workflow Design Patterns — An Overview | by Craig Li, Ph.D | Binome | Medium</a></p><p><strong>一句话摘要</strong>: 探讨AI代理工作流设计模式，分为反思型和规划型。</p><p><strong>能解决什么问题</strong>: 如何设计AI代理以模拟人类推理，执行任务并迭代。</p><p><strong>产品应用</strong>: 可以应用于实际产品，通过工作流模式灵活处理不同问题。</p><p><strong>示例场景</strong>: 使用ReAct模式集成工具增强AI代理能力。</p><hr><h3 id="_5-代理式用户体验-为智能代理设计系统的7个原则" tabindex="-1">5. 代理式用户体验：为智能代理设计系统的7个原则 <a class="header-anchor" href="#_5-代理式用户体验-为智能代理设计系统的7个原则" aria-label="Permalink to &quot;5. 代理式用户体验：为智能代理设计系统的7个原则&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/design-bootcamp/agentic-ux-7-principles-for-designing-systems-with-agents-019512c2caa9" target="_blank" rel="noreferrer">Agentic UX: 7 principles for designing systems with agents</a></p><p><strong>一句话摘要</strong>: 设计智能代理系统时应考虑的上下文共享和跨功能对齐原则。</p><p><strong>能解决什么问题</strong>: 解决智能代理在用户体验中的上下文断裂和信任问题。</p><p><strong>产品应用</strong>: 适用于需要智能代理辅助决策和操作的产品，如客服机器人。</p><p><strong>示例场景</strong>: 在线客服系统中的智能助手自动回复用户问题。</p><hr><h3 id="_6-ai交互模式-让用户识别并互动ai驱动功能" tabindex="-1">6. AI交互模式：让用户识别并互动AI驱动功能 <a class="header-anchor" href="#_6-ai交互模式-让用户识别并互动ai驱动功能" aria-label="Permalink to &quot;6. AI交互模式：让用户识别并互动AI驱动功能&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/@flik185/ai-interaction-patterns-giving-users-ways-to-recognize-and-interact-with-ai-driven-features-22055a91206b" target="_blank" rel="noreferrer">AI Interaction Patterns: Giving Users Ways to Recognize and Interact With Ai-Driven Features</a></p><p><strong>一句话摘要</strong>: 通过交互模式建立人与AI的信任关系</p><p><strong>能解决什么问题</strong>: 如何让用户轻松识别并互动AI功能</p><p><strong>产品应用</strong>: 适用于AI工具，如聊天机器人、分析仪表板等</p><p><strong>示例场景</strong>: 聊天机器人提供调整响应方式的功能</p><hr><h3 id="_7-人工智能用户体验设计模式" tabindex="-1">7. 人工智能用户体验设计模式 <a class="header-anchor" href="#_7-人工智能用户体验设计模式" aria-label="Permalink to &quot;7. 人工智能用户体验设计模式&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://lukelance.medium.com/ai-ux-design-patterns-53d9e378f808" target="_blank" rel="noreferrer">AI UX Design Patterns. Artificial Intelligence brings a new… | by Luke Bennis | Medium</a></p><p><strong>一句话摘要</strong>: 汇总AI体验中的关键交互模式</p><p><strong>能解决什么问题</strong>: 帮助设计师在AI产品中做出更好的UX决策</p><p><strong>产品应用</strong>: 可作为设计参考，评估哪些模式最适合产品和用户</p><p><strong>示例场景</strong>: 设计一个使用AI的聊天机器人界面</p><hr><h3 id="_8-在cursor中使用ai可读设计系统进行设计" tabindex="-1">8. 在Cursor中使用AI可读设计系统进行设计 <a class="header-anchor" href="#_8-在cursor中使用ai可读设计系统进行设计" aria-label="Permalink to &quot;8. 在Cursor中使用AI可读设计系统进行设计&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/design-bootcamp/working-with-ai-readable-design-systems-in-cursor-2bba9c9c09d9" target="_blank" rel="noreferrer">Designing with AI-readable design systems in Cursor</a></p><p><strong>一句话摘要</strong>: AI直接根据产品需求和UX规范生成完整产品流程</p><p><strong>能解决什么问题</strong>: 提高设计效率，确保设计遵循统一的设计系统</p><p><strong>产品应用</strong>: 适用于需要快速原型制作和设计系统一致性的产品开发</p><p><strong>示例场景</strong>: 设计师使用现有网站截图生成符合设计系统的原型</p><hr><h3 id="_9-ai在设计中的应用-改变我们的创作方式" tabindex="-1">9. AI在设计中的应用：改变我们的创作方式 <a class="header-anchor" href="#_9-ai在设计中的应用-改变我们的创作方式" aria-label="Permalink to &quot;9. AI在设计中的应用：改变我们的创作方式&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://www.figma.com/resource-library/ai-in-design" target="_blank" rel="noreferrer">AI in Design: Transforming the Way We Create - Figma</a></p><p><strong>一句话摘要</strong>: AI正在改变设计工作流程，提高效率和创造力。</p><p><strong>能解决什么问题</strong>: 解决设计过程中耗时的任务自动化和创意生成问题。</p><p><strong>产品应用</strong>: 可以应用到产品设计、UI/UX设计中，通过AI生成设计选项和素材。</p><p><strong>示例场景</strong>: 设计师使用AI快速生成多个界面布局进行用户测试。</p><hr><h3 id="_10-为代理型用户体验设计指南" tabindex="-1">10. 为代理型用户体验设计指南 <a class="header-anchor" href="#_10-为代理型用户体验设计指南" aria-label="Permalink to &quot;10. 为代理型用户体验设计指南&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/ai-ux-designers/era-of-agentive-ux-not-agentic-64dd765a0372" target="_blank" rel="noreferrer">Designing for Agentive UX — A Guide</a></p><p><strong>一句话摘要</strong>: 设计代理型用户体验，关注用户的长期需求和未来可能性。</p><p><strong>能解决什么问题</strong>: 解决用户在数字环境中快速完成任务的同时，发现未知需求的问题。</p><p><strong>产品应用</strong>: 可应用于个性化推荐系统，通过算法分析用户数据，预测并满足用户潜在需求。</p><p><strong>示例场景</strong>: 智能助手根据用户行为和偏好，自动推荐可能感兴趣的内容。</p><hr>',75)])])}const u=t(o,[["render",s]]);export{c as __pageData,u as default};
